// SPDX-License-Identifier: Apache-2.0
// SPDX-FileCopyrightText: Copyright (c) 2026 Stiftelsen Digipomps and HAVEN contributors

import Foundation
import Vapor
@preconcurrency import CellBase
@preconcurrency import CellVapor

/// The general Cell bridge.
///
/// A Cell reached over a bridge must expose exactly the same protocol surface as
/// a local one — that transparency is what lets Cell logic stay ignorant of
/// where its peers live, and it is the property HAVEN is built on. The route
/// that provided it (`/bridgehead/:pubId/:bridgeId` in `VaporBridgehead`) was
/// removed on 2026-07-13 by `14b50a51`, correctly, because it authenticated
/// nothing: any caller could open a bridge to any published Cell. Nothing
/// replaced it, so from that day every `cell://<host>/<Cell>` reference in the
/// HAVEN app failed with a websocket handshake 404. Measured 2026-09-02 on both
/// staging and production: 40 of 40 Cells unreachable.
///
/// This route restores the transparency and keeps the reason the old one was
/// removed. The upgrade now carries a proof of origin, and the caller's proven
/// identity is what the bridge runs commands for. Two proof kinds are accepted:
///
/// - **Identity proof** — an `IdentitySigningChallenge` signed by the caller's
///   own vault key. Asymmetric, so nothing secret ships in a client binary. This
///   is the path a HAVEN app build uses.
/// - **Sprout porthole contract** — an access contract issued by the resolver
///   against an explicit purpose, goal and interests. This is the path for a
///   caller that has no vault identity of its own, and it proves *why* rather
///   than only *who*.
///
/// What this route deliberately does **not** do is decide which Cells a caller
/// may read. Admission stays where it belongs: with the Cell, through its own
/// `Agreement` and `admit(context:)`. The socket proves who is calling; the Cell
/// decides what that caller is allowed to see. An allowlist here would move
/// authority away from the Cell and reintroduce exactly the drift that let a
/// name list and a catalog disagree.
struct VaporCellBridge: RouteCollection {

    // MARK: - Configuration

    struct Configuration: Sendable {
        var enabled: Bool
        var websocketEndpointComponents: [String]
        /// The authority a proof must be addressed to, so a proof minted for one
        /// host cannot be replayed against another.
        var audience: String
        var maximumHandshakesPerMinute: Int
        var maximumConnections: Int

        static func fromEnvironment(_ environment: Environment) -> Configuration {
            let endpoint = normalized(Environment.get("HAVEN_CELL_BRIDGE_WEBSOCKET_ENDPOINT")) ?? "bridgehead"
            return Configuration(
                // Enabled by default. The explicit off-switch takes precedence
                // when both environment switches are set.
                enabled: truthy(Environment.get("HAVEN_CELL_BRIDGE_DISABLED")) == false
                    && (truthy(Environment.get("HAVEN_CELL_BRIDGE_ENABLED"))
                        || normalized(Environment.get("HAVEN_CELL_BRIDGE_ENABLED")) == nil),
                websocketEndpointComponents: endpoint
                    .split(separator: "/")
                    .map(String.init)
                    .filter { $0.isEmpty == false },
                audience: normalized(Environment.get("HAVEN_CELL_BRIDGE_AUDIENCE"))
                    ?? normalized(Environment.get("RP_ID"))
                    ?? "localhost",
                maximumHandshakesPerMinute: intValue("HAVEN_CELL_BRIDGE_MAX_HANDSHAKES_PER_MINUTE", default: 60, min: 1, max: 6000),
                maximumConnections: intValue("HAVEN_CELL_BRIDGE_MAX_CONNECTIONS", default: 128, min: 1, max: 4096)
            )
        }

        private static func normalized(_ raw: String?) -> String? {
            guard let trimmed = raw?.trimmingCharacters(in: .whitespacesAndNewlines),
                  trimmed.isEmpty == false else { return nil }
            return trimmed
        }

        private static func truthy(_ raw: String?) -> Bool {
            guard let value = normalized(raw)?.lowercased() else { return false }
            return ["1", "true", "yes", "on"].contains(value)
        }

        private static func intValue(_ key: String, default fallback: Int, min lower: Int, max upper: Int) -> Int {
            guard let raw = normalized(Environment.get(key)), let parsed = Int(raw) else { return fallback }
            return Swift.min(Swift.max(parsed, lower), upper)
        }
    }

    // MARK: - Proof

    enum ProofKind: String, Sendable {
        case identityChallenge = "identity_challenge"
        case sproutContract = "sprout_contract"
    }

    struct ProvenCaller: Sendable {
        let identity: Identity
        let kind: ProofKind
        /// Only a Sprout contract states a purpose. An identity proof says who,
        /// not why, and this stays nil — the report must not imply otherwise.
        let purpose: String?
    }

    enum ProofError: String, Error {
        case missingProof = "missing_proof"
        case malformedProof = "malformed_proof"
        case unknownKeyMaterial = "unknown_key_material"
        case invalidScope = "invalid_scope"
        case invalidSignature = "invalid_signature"
        case replayed = "replayed"
        case contractRejected = "contract_rejected"
    }

    private let configuration: Configuration
    private let connections = CellBridgeConnectionRegistry()
    private let limiter = CellBridgeHandshakeLimiter()

    init(configuration: Configuration) {
        self.configuration = configuration
    }

    // MARK: - Routes

    func boot(routes: RoutesBuilder) throws {
        guard configuration.enabled else {
            // HAVEN_CELL_BRIDGE_DISABLED is the operator's explicit off-switch.
            return
        }
        guard configuration.websocketEndpointComponents.isEmpty == false else { return }

        let bridgeRoutes = routes.grouped(configuration.websocketEndpointComponents.map(PathComponent.constant))
        let audience = configuration.audience
        let maximumHandshakesPerMinute = configuration.maximumHandshakesPerMinute
        let maximumConnections = configuration.maximumConnections
        let limiter = self.limiter
        let connections = self.connections

        bridgeRoutes.webSocket(
            [.parameter("cellName"), .parameter("bridgeID")],
            maxFrameSize: 65_536,
            shouldUpgrade: { request async throws -> HTTPHeaders? in
                guard await limiter.allow(
                    key: Self.rateLimitKey(for: request),
                    limit: maximumHandshakesPerMinute
                ) else {
                    request.logger.warning("Cell bridge handshake rejected: rate limited")
                    return nil
                }
                guard let cellName = Self.normalizedCellName(request.parameters.get("cellName")),
                      let bridgeID = request.parameters.get("bridgeID"),
                      UUID(uuidString: bridgeID) != nil else {
                    return nil
                }
                do {
                    // Verified here so an unproven caller never reaches the
                    // upgrade, and verified again in the handler because
                    // `shouldUpgrade` cannot hand its result forward.
                    _ = try await Self.provenCaller(
                        request: request,
                        cellName: cellName,
                        audience: audience
                    )
                    return Self.securityHeaders()
                } catch {
                    let reason = (error as? ProofError)?.rawValue ?? "rejected"
                    request.logger.warning("Cell bridge handshake rejected for \(cellName): \(reason)")
                    return nil
                }
            }
        ) { request, webSocket async in
            guard let resolver = CellBase.defaultCellResolver else {
                try? await webSocket.close(code: .unexpectedServerError)
                return
            }
            do {
                guard let cellName = Self.normalizedCellName(request.parameters.get("cellName")),
                      let bridgeID = request.parameters.get("bridgeID"),
                      UUID(uuidString: bridgeID) != nil else {
                    try? await webSocket.close(code: .policyViolation)
                    return
                }
                let caller = try await Self.provenCaller(
                    request: request,
                    cellName: cellName,
                    audience: audience
                )

                // The publisher identity resolves the target Cell locally; the
                // proven caller is who the Cell will see on every command, and
                // therefore who its Agreement judges.
                let (publisherIdentity, _, _) = try await VaporBridgehead()
                    .identityForBridgeReference(cellName)

                guard await resolver.cellUUID(for: cellName) != nil else {
                    request.logger.warning("Cell bridge target not registered: \(cellName)")
                    try? await webSocket.close(code: .policyViolation)
                    return
                }
                guard await connections.reserve(bridgeID: bridgeID, maximum: maximumConnections) else {
                    request.logger.warning("Cell bridge rejected: connection limit reached")
                    try? await webSocket.close(code: .policyViolation)
                    return
                }

                let transport = VaporBridgeTransport(webSocket: webSocket)
                let config = await VaporBridgehead.bridgeConfig(
                    publisherIdentity: publisherIdentity,
                    publisherReference: cellName,
                    bridgeReference: bridgeID,
                    transport: transport
                )
                let bridge = try await BridgeBase(config)

                webSocket.onClose.whenComplete { _ in
                    let uuid = bridge.uuid
                    Task {
                        await connections.release(bridgeID: bridgeID)
                        if let resolver = CellBase.defaultCellResolver {
                            await resolver.unregisterEmitCell(uuid: uuid)
                        }
                    }
                }

                try await bridge.setTransport(transport, connection: .inbound(publisherUuid: cellName))
                if let staleUUID = await resolver.cellUUID(for: bridgeID) {
                    await resolver.unregisterEmitCell(uuid: staleUUID)
                }
                try await resolver.registerNamedEmitCell(
                    name: bridgeID,
                    emitCell: bridge,
                    scope: .template,
                    identity: publisherIdentity
                )
                request.logger.info(
                    "Cell bridge opened cell=\(cellName) proof=\(caller.kind.rawValue) caller=\(caller.identity.uuid.prefix(8))"
                )
                let ready = BridgeCommand(cmd: "ready", payload: .string(cellName), cid: 0)
                try await transport.sendData(JSONEncoder().encode(ready))
            } catch {
                request.logger.error("Cell bridge upgrade failed: \(String(describing: error))")
                try? await webSocket.close(code: .policyViolation)
            }
        }
    }

    // MARK: - Proof verification

    static func provenCaller(
        request: Request,
        cellName: String,
        audience: String,
        now: Date = Date()
    ) async throws -> ProvenCaller {
        if let proof = request.query[String.self, at: "bridge_proof"] {
            let signature = request.query[String.self, at: "bridge_signature"]
            return try await identityProvenCaller(
                proofB64URL: proof,
                signatureB64URL: signature,
                cellName: cellName,
                audience: audience,
                now: now
            )
        }
        if let payload = request.query[String.self, at: "contract_payload_b64url"] {
            return try await contractProvenCaller(
                payloadB64URL: payload,
                hashB64URL: request.query[String.self, at: "contract_sha256_b64url"],
                cellName: cellName,
                audience: audience,
                request: request,
                now: now
            )
        }
        throw ProofError.missingProof
    }

    /// An `IdentitySigningChallenge` the caller signed with its own vault key.
    /// The challenge carries the public key fingerprint, so the key that must
    /// verify the signature is named by the signed payload itself — a caller
    /// cannot present one key and a challenge minted for another.
    private static func identityProvenCaller(
        proofB64URL: String,
        signatureB64URL: String?,
        cellName: String,
        audience: String,
        now: Date
    ) async throws -> ProvenCaller {
        guard let signatureB64URL else { throw ProofError.missingProof }
        let challengeData: Data
        let signature: Data
        do {
            challengeData = try SproutBase64URL.decode(proofB64URL)
            signature = try SproutBase64URL.decode(signatureB64URL)
        } catch {
            throw ProofError.malformedProof
        }
        guard challengeData.count <= IdentitySigningChallenge.maximumEncodedBytes else {
            throw ProofError.malformedProof
        }
        guard let decoded = try? JSONDecoder().decode(IdentitySigningChallenge.self, from: challengeData) else {
            throw ProofError.malformedProof
        }
        guard let identity = makeIdentity(fromFingerprint: decoded.publicKeyFingerprint, uuid: decoded.identityUUID) else {
            throw ProofError.unknownKeyMaterial
        }

        let challenge: IdentitySigningChallenge
        do {
            challenge = try IdentitySigningChallenge.validateSigningData(challengeData, for: identity, now: now)
        } catch {
            throw ProofError.malformedProof
        }
        guard Self.scopeMatchesRemoteBridgeAuthority(
            challenge: challenge,
            cellName: cellName,
            audience: audience
        ) else {
            throw ProofError.invalidScope
        }
        guard IdentityPublicKeySignatureVerifier.verify(
            signature: signature,
            messageData: challengeData,
            identity: identity
        ) else {
            throw ProofError.invalidSignature
        }
        if let replayStore = CellBase.signingChallengeReplayStore {
            guard await replayStore.consume(challenge, now: now) == .accepted else {
                throw ProofError.replayed
            }
        }
        return ProvenCaller(identity: identity, kind: .identityChallenge, purpose: nil)
    }

    /// A Sprout porthole access contract. The resolver only issues one against an
    /// explicit purpose, goal and interests, so this path proves intent as well
    /// as identity. Bound to this exact bridge URL so a contract minted for one
    /// Cell cannot open another.
    private static func contractProvenCaller(
        payloadB64URL: String,
        hashB64URL: String?,
        cellName: String,
        audience: String,
        request: Request,
        now: Date
    ) async throws -> ProvenCaller {
        let payload: Data
        do {
            payload = try SproutBase64URL.decode(payloadB64URL)
        } catch {
            throw ProofError.malformedProof
        }
        if let hashB64URL, SproutHashing.sha256Base64URL(payload) != hashB64URL {
            throw ProofError.malformedProof
        }
        guard let contract = try? JSONDecoder().decode(SproutPortholeAccessContract.self, from: payload) else {
            throw ProofError.malformedProof
        }
        guard contract.client_kind == .native,
              contract.porthole_protocol == .cellprotocol else {
            throw ProofError.contractRejected
        }
        guard contract.isExpired(now: now) == false else {
            throw ProofError.contractRejected
        }
        guard contract.scaffold_domain.lowercased() == audience.lowercased() else {
            throw ProofError.invalidScope
        }
        guard contract.bridge_endpoint.hasSuffix("/\(cellName)")
                || contract.bridge_endpoint.contains("/\(cellName)/") else {
            throw ProofError.invalidScope
        }
        guard (try? contract.verifySignature()) == true else {
            throw ProofError.invalidSignature
        }
        guard contract.purpose.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false else {
            throw ProofError.invalidScope
        }
        let identity = try request.application.sproutResolverService.makeNativeBridgeIdentity(for: contract)
        return ProvenCaller(identity: identity, kind: .sproutContract, purpose: contract.purpose)
    }

    // MARK: - Scope vocabulary

    /// The scope a caller must have signed for.
    ///
    /// This deliberately does not invent a vocabulary. `CellResolver` already
    /// mints exactly this challenge before it opens a remote Cell bridge — see
    /// `proveRemoteBridgePrincipal`, which calls
    /// `IdentitySigningChallenge.proveControl` with domain
    /// `cellprotocol.remote-bridge`, action `resolve`, audience `CellResolver`
    /// and the endpoint as resource. Until now that proof was computed and
    /// thrown away: it was used only to derive a local cache key, never sent.
    /// The server therefore asks for precisely the proof the client already
    /// knows how to make, and reuses the client's own resource function so the
    /// two can never drift.
    static let bridgeAuthorityDomain = "cellprotocol.remote-bridge"
    static let bridgeAuthorityAction = "resolve"
    static let bridgeAuthorityAudience = "CellResolver"

    /// The logical endpoint a caller must have bound its proof to. A proof for
    /// one Cell on one host cannot open another.
    static func logicalEndpoint(cellName: String, audience: String) -> String {
        "cell://\(audience)/\(cellName)"
    }

    static func scopeMatchesRemoteBridgeAuthority(
        challenge: IdentitySigningChallenge,
        cellName: String,
        audience: String
    ) -> Bool {
        guard challenge.domain == bridgeAuthorityDomain,
              challenge.action == bridgeAuthorityAction,
              challenge.audience == bridgeAuthorityAudience else {
            return false
        }
        let endpoint = logicalEndpoint(cellName: cellName, audience: audience)
        // Same transformation the client applied, from the client's own code:
        // long endpoints are hashed so the scope stays inside the challenge's
        // character bound.
        return challenge.resource == CellResolver.remoteBridgeAuthorityChallengeResource(for: endpoint)
    }

    // MARK: - Helpers

    /// `Identity.signingPublicKeyFingerprint` is `algorithm:curve:base64(key)`.
    /// Rebuilding the key from the fingerprint means the signed payload names its
    /// own verification key; there is no second, unsigned key parameter to
    /// disagree with it.
    static func makeIdentity(fromFingerprint fingerprint: String?, uuid: String) -> Identity? {
        guard let fingerprint, uuid.isEmpty == false else { return nil }
        let parts = fingerprint.split(separator: ":", maxSplits: 2, omittingEmptySubsequences: false)
        guard parts.count == 3,
              let algorithm = CurveAlgorithm(rawValue: String(parts[0])),
              let curve = CurveType(rawValue: String(parts[1])),
              let keyData = Data(base64Encoded: String(parts[2])),
              keyData.isEmpty == false,
              keyData.count <= 256 else {
            return nil
        }
        let identity = Identity(uuid, displayName: "cell-bridge-caller", identityVault: nil)
        identity.publicSecureKey = SecureKey(
            date: Date(),
            privateKey: false,
            use: .signature,
            algorithm: algorithm,
            size: 256,
            curveType: curve,
            x: nil,
            y: nil,
            compressedKey: keyData
        )
        return identity
    }

    static func normalizedCellName(_ raw: String?) -> String? {
        guard let trimmed = raw?.trimmingCharacters(in: .whitespacesAndNewlines),
              trimmed.isEmpty == false,
              trimmed.count <= 128,
              trimmed.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "-" || $0 == "_" || $0 == "." })
        else {
            return nil
        }
        return trimmed
    }

    private static func rateLimitKey(for request: Request) -> String {
        request.headers.first(name: "X-Forwarded-For")?
            .split(separator: ",").first.map { $0.trimmingCharacters(in: .whitespaces) }
            ?? request.remoteAddress?.ipAddress
            ?? "unknown"
    }

    private static func securityHeaders() -> HTTPHeaders {
        var headers = HTTPHeaders()
        headers.replaceOrAdd(name: "X-Content-Type-Options", value: "nosniff")
        headers.replaceOrAdd(name: "X-Frame-Options", value: "DENY")
        headers.replaceOrAdd(name: "Referrer-Policy", value: "no-referrer")
        return headers
    }
}

// MARK: - Small actors

actor CellBridgeConnectionRegistry {
    private var active: Set<String> = []

    func reserve(bridgeID: String, maximum: Int) -> Bool {
        guard active.count < maximum, active.contains(bridgeID) == false else { return false }
        active.insert(bridgeID)
        return true
    }

    func release(bridgeID: String) {
        active.remove(bridgeID)
    }
}

actor CellBridgeHandshakeLimiter {
    private var windows: [String: (start: TimeInterval, count: Int)] = [:]

    func allow(key: String, limit: Int, now: Date = Date()) -> Bool {
        let nowInterval = now.timeIntervalSince1970
        windows = windows.filter { nowInterval - $0.value.start < 60 }
        var window = windows[key] ?? (start: nowInterval, count: 0)
        if nowInterval - window.start >= 60 {
            window = (start: nowInterval, count: 0)
        }
        guard window.count < limit else { return false }
        window.count += 1
        windows[key] = window
        return true
    }
}

