    private let reconciliationStore: any ReconciliationStore
    private let spentSetStore: any SpentSetStore
    private let paymentSessionCreator: any PaymentSessionCreating
    private let mintConfiguration: MintConfiguration
    private let mintSigner: any MintSigner
    private let stripeWebhookSecret: String?
    private let now: @Sendable () -> Date
    private let ledgerEncoder: JSONEncoder
    private let ledgerDecoder: JSONDecoder

    public init(
        store: InMemoryFundingStore = InMemoryFundingStore(),
        spentSetStore: any SpentSetStore = InMemorySpentSetStore(),
        paymentSessionCreator: any PaymentSessionCreating = EnvironmentStripePaymentSessionCreator(),
        mintConfiguration: MintConfiguration = MintConfiguration(),
        mintSigner: any MintSigner = DevelopmentMintSigner(),
        stripeWebhookSecret: String? = ProcessInfo.processInfo.environment["STRIPE_WEBHOOK_SECRET"],
        now: @escaping @Sendable () -> Date = { Date() }
    ) {
        self.productCatalogStore = store
        self.walletStore = store
        self.walletReservationStore = store
        self.quoteStore = store
        self.providerPaymentStore = store
        self.providerEventStore = store
        self.cashEventStore = store
        self.walletEventStore = store
        self.ledgerIdempotencyStore = store
        self.issuedCoinStore = store
        self.reconciliationStore = store
        self.spentSetStore = spentSetStore
        self.paymentSessionCreator = paymentSessionCreator
        self.mintConfiguration = mintConfiguration
        self.mintSigner = mintSigner
        self.stripeWebhookSecret = stripeWebhookSecret
        self.now = now
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        self.ledgerEncoder = encoder
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        self.ledgerDecoder = decoder
    }

    public init(
        productCatalogStore: any ProductCatalogStore,
        walletStore: any WalletStore,
        walletReservationStore: any WalletReservationStore,
        quoteStore: any QuoteStore,
        providerPaymentStore: any ProviderPaymentStore,
        providerEventStore: any ProviderEventStore,
        cashEventStore: any CashEventStore,
        walletEventStore: any WalletEventStore,
        ledgerIdempotencyStore: any LedgerIdempotencyStore,
        issuedCoinStore: any IssuedCoinStore,
        reconciliationStore: any ReconciliationStore,
        spentSetStore: any SpentSetStore = InMemorySpentSetStore(),
        paymentSessionCreator: any PaymentSessionCreating = EnvironmentStripePaymentSessionCreator(),
        mintConfiguration: MintConfiguration = MintConfiguration(),
        mintSigner: any MintSigner = DevelopmentMintSigner(),
        stripeWebhookSecret: String? = ProcessInfo.processInfo.environment["STRIPE_WEBHOOK_SECRET"],
        now: @escaping @Sendable () -> Date = { Date() }
    ) {
        self.productCatalogStore = productCatalogStore
        self.walletStore = walletStore
        self.walletReservationStore = walletReservationStore
        self.quoteStore = quoteStore
        self.providerPaymentStore = providerPaymentStore
        self.providerEventStore = providerEventStore
        self.cashEventStore = cashEventStore
        self.walletEventStore = walletEventStore
        self.ledgerIdempotencyStore = ledgerIdempotencyStore
        self.issuedCoinStore = issuedCoinStore
        self.reconciliationStore = reconciliationStore
        self.spentSetStore = spentSetStore
        self.paymentSessionCreator = paymentSessionCreator
        self.mintConfiguration = mintConfiguration
        self.mintSigner = mintSigner
        self.stripeWebhookSecret = stripeWebhookSecret
        self.now = now
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        self.ledgerEncoder = encoder
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        self.ledgerDecoder = decoder
    }

