    public func createWalletReservation(
        walletID: UUID,
        request: CreateWalletReservationRequest
    ) async throws -> WalletReservationResponse {
        guard let wallet = try await walletStore.wallet(walletID: walletID),
              let balance = try await walletStore.balance(walletID: wallet.walletID) else {
            throw FundingServiceError.unknownWallet(walletID)
        }

        guard let quote = try await quoteStore.quote(quoteID: request.quoteID) else {
            throw FundingServiceError.unknownQuote(request.quoteID)
        }

        guard quote.walletID == wallet.walletID else {
            throw FundingServiceError.quoteWalletMismatch(quoteID: quote.quoteID, walletID: wallet.walletID)
        }

        guard quote.expiresAt > Date() else {
            throw FundingServiceError.quoteExpired(quote.quoteID)
        }

        guard quote.amountNOKOre > 0 else {
            throw FundingServiceError.invalidAmount(quote.amountNOKOre)
        }

        let resourceID = normalizedResourceID(request.resourceID ?? quote.resourceID)
        if let replay: WalletReservationResponse = try await replayIdempotentResponse(
            key: request.idempotencyKey,
            action: .walletReserve,
            identityScope: wallet.customerID,
            resourceID: resourceID,
            requestHash: hashRequest([
                "walletID": wallet.walletID.uuidString,
                "quoteID": quote.quoteID.uuidString,
                "resourceID": resourceID ?? "",
                "amount": "\(quote.amountNOKOre)"
            ])
        ) {
            return replay
        }

        guard balance.availableNOKOre >= quote.amountNOKOre else {
            throw FundingServiceError.insufficientWalletBalance(
                walletID: wallet.walletID,
                availableNOKOre: balance.availableNOKOre,
                requiredNOKOre: quote.amountNOKOre
            )
        }

        let reservation = WalletReservationRecord(
            walletID: wallet.walletID,
            customerID: wallet.customerID,
            quoteID: quote.quoteID,
            resourceID: resourceID,
            reservedUnitName: quote.unitName,
            reservedUnitAmount: quote.unitAmount,
            reservedNOKOre: quote.amountNOKOre,
            expiresAt: quote.expiresAt
        )

        try await walletReservationStore.upsertReservation(reservation)
        try await walletEventStore.insertWalletEvent(
            WalletEventRecord(
                walletID: wallet.walletID,
                customerID: wallet.customerID,
                quoteID: quote.quoteID,
                cashEventID: nil,
                reservationID: reservation.reservationID,
                eventType: .walletReserved,
                unitName: quote.unitName,
                unitAmount: quote.unitAmount,
                nokReferenceAmountOre: quote.amountNOKOre
            )
        )
        try await walletStore.upsertBalance(
            WalletBalanceProjection(
                walletID: balance.walletID,
                unitName: balance.unitName,
                availableUnits: balance.availableUnits - quote.unitAmount,
                reservedUnits: balance.reservedUnits + quote.unitAmount,
                consumedUnits: balance.consumedUnits,
                availableNOKOre: balance.availableNOKOre - quote.amountNOKOre,
                reservedNOKOre: balance.reservedNOKOre + quote.amountNOKOre,
                consumedNOKOre: balance.consumedNOKOre,
                updatedAt: Date()
            )
        )

        let response = WalletReservationResponse(record: reservation)
        try await storeIdempotentResponse(
            response,
            key: request.idempotencyKey,
            action: .walletReserve,
            identityScope: wallet.customerID,
            resourceID: resourceID,
            requestHash: hashRequest([
                "walletID": wallet.walletID.uuidString,
                "quoteID": quote.quoteID.uuidString,
                "resourceID": resourceID ?? "",
                "amount": "\(quote.amountNOKOre)"
            ])
        )
        return response
    }

    public func releaseWalletReservation(
        walletID: UUID,
        reservationID: UUID,
        request: ReleaseWalletReservationRequest
    ) async throws -> WalletReservationResponse {
        guard let wallet = try await walletStore.wallet(walletID: walletID),
              let balance = try await walletStore.balance(walletID: wallet.walletID) else {
            throw FundingServiceError.unknownWallet(walletID)
        }

        guard let reservation = try await walletReservationStore.reservation(reservationID: reservationID) else {
            throw FundingServiceError.unknownReservation(reservationID)
        }

        guard reservation.walletID == wallet.walletID else {
            throw FundingServiceError.unknownReservation(reservationID)
        }

        if reservation.status == .released {
            return WalletReservationResponse(record: reservation)
        }

        guard reservation.status == .active else {
            throw FundingServiceError.reservationNotActive(reservationID)
        }

        if let replay: WalletReservationResponse = try await replayIdempotentResponse(
            key: request.idempotencyKey,
            action: .walletRelease,
            identityScope: wallet.customerID,
            resourceID: reservation.resourceID,
            requestHash: hashRequest([
                "walletID": wallet.walletID.uuidString,
                "reservationID": reservation.reservationID.uuidString,
                "reason": request.reason ?? ""
            ])
        ) {
            return replay
        }

        let released = reservation.with(status: .released, releasedAt: Date())
        try await walletReservationStore.upsertReservation(released)
        try await walletEventStore.insertWalletEvent(
            WalletEventRecord(
                walletID: wallet.walletID,
                customerID: wallet.customerID,
                quoteID: reservation.quoteID,
                cashEventID: nil,
                reservationID: reservation.reservationID,
                eventType: .walletReservationReleased,
                unitName: reservation.reservedUnitName,
                unitAmount: reservation.reservedUnitAmount,
                nokReferenceAmountOre: reservation.reservedNOKOre
            )
        )

        try await walletStore.upsertBalance(
            WalletBalanceProjection(
                walletID: balance.walletID,
                unitName: balance.unitName,
                availableUnits: balance.availableUnits + reservation.reservedUnitAmount,
                reservedUnits: balance.reservedUnits - reservation.reservedUnitAmount,
                consumedUnits: balance.consumedUnits,
                availableNOKOre: balance.availableNOKOre + reservation.reservedNOKOre,
                reservedNOKOre: balance.reservedNOKOre - reservation.reservedNOKOre,
                consumedNOKOre: balance.consumedNOKOre,
                updatedAt: Date()
            )
        )

        _ = request.reason
        let response = WalletReservationResponse(record: released)
        try await storeIdempotentResponse(
            response,
            key: request.idempotencyKey,
            action: .walletRelease,
            identityScope: wallet.customerID,
            resourceID: reservation.resourceID,
            requestHash: hashRequest([
                "walletID": wallet.walletID.uuidString,
                "reservationID": reservation.reservationID.uuidString,
                "reason": request.reason ?? ""
            ])
        )
        return response
    }

    public func createQuote(_ request: CreateQuoteRequest) async throws -> CreateQuoteResponse {
        guard request.quantity > 0 else {
            throw FundingServiceError.invalidQuantity(request.quantity)
        }

        guard let product = try await productCatalogStore.product(productID: request.productID) else {
            throw FundingServiceError.unknownProduct(request.productID)
        }

        guard product.isActive else {
            throw FundingServiceError.inactiveProduct(request.productID)
        }

        let wallet = try await resolveWallet(customerID: request.customerID, walletID: request.walletID)
        let amount = product.unitPriceNOKOre * Int64(request.quantity)
        guard amount >= 0 else {
            throw FundingServiceError.invalidAmount(amount)
        }

        let quote = PriceQuoteRecord(
            walletID: wallet.walletID,
            customerID: request.customerID,
            productID: request.productID,
            resourceID: request.resourceID,
            quantity: request.quantity,
            amountNOKOre: amount,
            unitAmount: amount,
            taxCode: product.taxCode,
            taxBehavior: product.taxBehavior,
            expiresAt: Date().addingTimeInterval(30 * 60)
        )

        try await quoteStore.upsertQuote(quote)
        return CreateQuoteResponse(record: quote)
    }

    public func createPaymentSession(_ request: CreatePaymentSessionRequest) async throws -> CreatePaymentSessionResponse {
        guard let quote = try await quoteStore.quote(quoteID: request.quoteID) else {
            throw FundingServiceError.unknownQuote(request.quoteID)
        }

        guard quote.expiresAt > Date() else {
            throw FundingServiceError.quoteExpired(quote.quoteID)
        }

        guard request.provider == .stripe else {
            throw FundingServiceError.unsupportedPaymentProvider(request.provider)
        }

        let requestedProviderPaymentRef = makeProviderPaymentRef(provider: request.provider)
        let session = try await paymentSessionCreator.createStripeCheckoutSession(
            StripeCheckoutSessionRequest(
                providerPaymentRef: requestedProviderPaymentRef,
                quoteID: quote.quoteID,
                walletID: quote.walletID,
                customerID: quote.customerID,
                amountNOKOre: quote.amountNOKOre,
                currency: "NOK",
                returnURL: request.returnURL,
                cancelURL: request.cancelURL
            )
        )
        let payment = ProviderPaymentRecord(
            provider: request.provider,
            providerPaymentRef: session.providerPaymentRef,
            walletID: quote.walletID,
            customerID: quote.customerID,
            quoteID: quote.quoteID,
            requestedAmountNOKOre: quote.amountNOKOre,
            status: .initiated,
            checkoutURL: session.checkoutURL
        )

        try await providerPaymentStore.upsertPayment(payment)
        return CreatePaymentSessionResponse(record: payment, checkoutURL: session.checkoutURL)
    }

    public func ingestStripeWebhook(body: Data, headers: [String: String]) async throws -> StripeWebhookAcknowledgement {
        guard let signatureHeader = headerValue("Stripe-Signature", in: headers) else {
            throw FundingServiceError.missingWebhookSignature
        }
        guard let secret = stripeWebhookSecret?.trimmingCharacters(in: .whitespacesAndNewlines), !secret.isEmpty else {
            throw FundingServiceError.webhookSecretNotConfigured
        }
        guard StripeWebhookSigning.isValid(header: signatureHeader, payload: body, secret: secret, now: now()) else {
            throw FundingServiceError.invalidWebhookSignature
        }

        let envelope = try JSONDecoder().decode(StripeWebhookEnvelope.self, from: body)
        if try await providerEventStore.providerEvent(provider: .stripe, providerEventRef: envelope.id) != nil {
            return StripeWebhookAcknowledgement(
                accepted: true,
                alreadyProcessed: true,
                providerEventRef: envelope.id,
                effect: "duplicate_ignored"
            )
        }

        let occurredAt = envelope.created.map(Date.init(timeIntervalSince1970:)) ?? Date()
        let providerEventRef = envelope.id
        let providerPaymentRef: String
        if envelope.type == "checkout.session.completed" {
            providerPaymentRef = envelope.data.object.id
        } else {
            providerPaymentRef = envelope.data.object.paymentIntent ?? envelope.data.object.id
        }
        let rawEvent = ProviderEventRecord(
            provider: .stripe,
            providerEventRef: providerEventRef,
            providerPaymentRef: providerPaymentRef,
            eventType: envelope.type,
            signatureVerified: true,
            occurredAt: occurredAt,
            payloadSHA256: FundingHashing.sha256Hex(body),
            rawBody: body,
            headers: headers
        )
        try await providerEventStore.insertProviderEvent(rawEvent)

        switch envelope.type {
        case "checkout.session.completed":
            guard envelope.data.object.paymentStatus == "paid" else {
                return StripeWebhookAcknowledgement(
                    accepted: true,
                    alreadyProcessed: false,
                    providerEventRef: providerEventRef,
                    effect: "checkout_not_paid"
                )
            }

            let amount = envelope.data.object.amountTotal
            guard let amount, amount >= 0 else {
                throw FundingServiceError.invalidStripeEventPayload
            }

            let payment = try await resolvePaymentForCapture(
                providerPaymentRef: providerPaymentRef,
                envelope: envelope,
                amount: amount
            )

            let updatedPayment = payment.with(status: .captured, requestedAmountNOKOre: max(payment.requestedAmountNOKOre, amount))
            try await providerPaymentStore.upsertPayment(updatedPayment)

            let cashEvent = CashEventRecord(
                providerPaymentID: updatedPayment.providerPaymentID,
                providerEventID: rawEvent.providerEventID,
                walletID: updatedPayment.walletID,
                customerID: updatedPayment.customerID,
                provider: .stripe,
                eventType: .paymentCaptured,
                grossAmountNOKOre: amount,
                netAmountNOKOre: amount,
                occurredAt: occurredAt
            )
            guard try await cashEventStore.insertPaymentCaptureIfAbsent(cashEvent) else {
                return StripeWebhookAcknowledgement(
                    accepted: true,
                    alreadyProcessed: true,
                    providerEventRef: providerEventRef,
                    effect: "economic_duplicate_ignored"
                )
            }

            let walletEvent = WalletEventRecord(
                walletID: updatedPayment.walletID,
                customerID: updatedPayment.customerID,
                quoteID: updatedPayment.quoteID,
                cashEventID: cashEvent.cashEventID,
                eventType: .walletCreditGranted,
                unitAmount: amount,
                nokReferenceAmountOre: amount,
                occurredAt: occurredAt
            )
            try await walletEventStore.insertWalletEvent(walletEvent)
            try await incrementWalletBalance(walletID: updatedPayment.walletID, amount: amount)

            return StripeWebhookAcknowledgement(
                accepted: true,
                alreadyProcessed: false,
                providerEventRef: providerEventRef,
                effect: "wallet_credited"
            )
        default:
            return StripeWebhookAcknowledgement(
                accepted: true,
                alreadyProcessed: false,
                providerEventRef: providerEventRef,
                effect: "stored_without_projection"
            )
        }
    }

    public func issueFromReservation(
        reservationID: UUID,
        request: IssueFromReservationRequest
    ) async throws -> IssueFromReservationResponse {
        guard !request.idempotencyKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw FundingServiceError.invalidIdempotencyKey
        }

        guard let reservation = try await walletReservationStore.reservation(reservationID: reservationID) else {
            throw FundingServiceError.unknownReservation(reservationID)
        }

        if let replay: IssueFromReservationResponse = try await replayIdempotentResponse(
            key: request.idempotencyKey,
            action: .issueFromReservation,
            identityScope: reservation.customerID,
            resourceID: reservation.resourceID,
            requestHash: hashRequest([
                "reservationID": reservation.reservationID.uuidString,
                "strategy": request.denominationStrategy.rawValue
            ])
        ) {
            return replay
        }

        guard reservation.status == .active else {
            throw FundingServiceError.reservationNotActive(reservationID)
        }
        guard reservation.reservedNOKOre > 0,
              let reservedAmount = UInt64(exactly: reservation.reservedNOKOre) else {
            throw FundingServiceError.invalidAmount(reservation.reservedNOKOre)
        }

        let denominations = request.denominationStrategy.split(amountMinorUnits: reservedAmount)
        guard !denominations.isEmpty,
              denominations.reduce(UInt64(0), +) == reservedAmount else {
            throw FundingServiceError.invalidDenominationStrategy
        }

        guard let balance = try await walletStore.balance(walletID: reservation.walletID) else {
            throw FundingServiceError.unknownWallet(reservation.walletID)
        }

        let issuedAt = now()
        let coins = denominations.enumerated().map { index, denomination in
            makeIssuedCoin(
                reservation: reservation,
                denomination: denomination,
                idempotencyKey: request.idempotencyKey,
                index: index
            )
        }

        let consumed = reservation.with(status: .consumed)
        try await walletReservationStore.upsertReservation(consumed)
        for coin in coins {
            try await issuedCoinStore.upsertIssuedCoin(
                IssuedCoinRecord(
                    serial: coin.serial,
                    walletID: reservation.walletID,
                    customerID: reservation.customerID,
                    reservationID: reservation.reservationID,
                    quoteID: reservation.quoteID,
                    resourceID: reservation.resourceID,
                    amountNOKOre: Int64(coin.denomMinorUnits),
                    issuedAt: issuedAt
                )
            )
        }
        try await walletEventStore.insertWalletEvent(
            WalletEventRecord(
                walletID: reservation.walletID,
                customerID: reservation.customerID,
                quoteID: reservation.quoteID,
                cashEventID: nil,
                reservationID: reservation.reservationID,
                eventType: .mintIssued,
                unitName: reservation.reservedUnitName,
                unitAmount: reservation.reservedUnitAmount,
                nokReferenceAmountOre: reservation.reservedNOKOre,
                occurredAt: issuedAt
            )
        )
        try await walletStore.upsertBalance(
            WalletBalanceProjection(
                walletID: balance.walletID,
                unitName: balance.unitName,
                availableUnits: balance.availableUnits,
                reservedUnits: balance.reservedUnits - reservation.reservedUnitAmount,
                consumedUnits: balance.consumedUnits + reservation.reservedUnitAmount,
                availableNOKOre: balance.availableNOKOre,
                reservedNOKOre: balance.reservedNOKOre - reservation.reservedNOKOre,
                consumedNOKOre: balance.consumedNOKOre + reservation.reservedNOKOre,
                updatedAt: issuedAt
            )
        )

        let response = IssueFromReservationResponse(
            reservationID: reservation.reservationID,
            walletID: reservation.walletID,
            customerID: reservation.customerID,
            resourceID: reservation.resourceID,
            issuedNOKOre: reservation.reservedNOKOre,
            denominationStrategy: request.denominationStrategy,
            coins: coins,
            issuedAt: issuedAt
        )
        try await storeIdempotentResponse(
            response,
            key: request.idempotencyKey,
            action: .issueFromReservation,
            identityScope: reservation.customerID,
            resourceID: reservation.resourceID,
            requestHash: hashRequest([
                "reservationID": reservation.reservationID.uuidString,
                "strategy": request.denominationStrategy.rawValue
            ])
        )
        return response
    }

    public func redeemWithLedger(_ request: RedeemWithLedgerRequest) async throws -> RedeemWithLedgerResponse {
        guard !request.idempotencyKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw FundingServiceError.invalidIdempotencyKey
        }
        guard request.bundle.resourceID == request.resourceID else {
            throw FundingServiceError.resourceMismatch(expected: request.bundle.resourceID, actual: request.resourceID)
        }

        let requestHash = hashRequest([
            "bundleHash": request.bundleHash,
            "resourceID": request.resourceID,
            "merchantID": request.merchantID,
            "amount": "\(request.bundle.totalMinorUnits)"
        ])
        if let replay: RedeemWithLedgerResponse = try await replayIdempotentResponse(
            key: request.idempotencyKey,
            action: .redeemWithLedger,
            identityScope: request.merchantID,
            resourceID: request.resourceID,
            requestHash: requestHash
        ) {
            return RedeemWithLedgerResponse(
                accepted: replay.accepted,
                alreadyProcessed: true,
                rejectionReason: replay.rejectionReason,
                receipt: replay.receipt,
                walletID: replay.walletID,
                customerID: replay.customerID,
                resourceID: replay.resourceID,
                merchantID: replay.merchantID,
                redeemedNOKOre: replay.redeemedNOKOre,
                occurredAt: replay.occurredAt
            )
        }

        let expectedHash = try BundleHasher.hash(bundle: request.bundle)
        guard expectedHash == request.bundleHash else {
            let response = redeemRejectedResponse(request, reason: .invalidBundleHash)
            try await storeIdempotentResponse(
                response,
                key: request.idempotencyKey,
                action: .redeemWithLedger,
                identityScope: request.merchantID,
                resourceID: request.resourceID,
                requestHash: requestHash
            )
            return response
        }

        let issuedCoins = try await resolveIssuedCoins(for: request.bundle)
        for coin in request.bundle.coins {
            if coin.signature.isEmpty {
                let response = redeemRejectedResponse(request, reason: .invalidCoinSignature)
                try await storeIdempotentResponse(
                    response,
                    key: request.idempotencyKey,
                    action: .redeemWithLedger,
                    identityScope: request.merchantID,
                    resourceID: request.resourceID,
                    requestHash: requestHash
                )
                return response
            }
            if try await spentSetStore.contains(serial: coin.serial) {
                let response = redeemRejectedResponse(request, reason: .doubleSpend)
                try await storeIdempotentResponse(
                    response,
                    key: request.idempotencyKey,
                    action: .redeemWithLedger,
                    identityScope: request.merchantID,
                    resourceID: request.resourceID,
                    requestHash: requestHash
                )
                return response
            }
        }

        guard let firstIssuedCoin = issuedCoins.first else {
            throw FundingServiceError.invalidStripeEventPayload
        }
        guard issuedCoins.allSatisfy({ $0.walletID == firstIssuedCoin.walletID && $0.customerID == firstIssuedCoin.customerID }) else {
            throw FundingServiceError.issuedCoinWalletMismatch
        }

        for coin in request.bundle.coins {
            try await spentSetStore.insert(
                serial: coin.serial,
                bundleHash: request.bundleHash,
                merchantID: request.merchantID
            )
        }

        let occurredAt = now()
        let amount = Int64(request.bundle.totalMinorUnits)
        let receiptSignature = mintSigner.signReceipt(
            bundleHash: request.bundleHash,
            merchantID: request.merchantID,
            merchantCreditRef: request.idempotencyKey,
            issuedAt: occurredAt,
            mintKeyID: mintConfiguration.mintKeyID
        )
        let receipt = SpendReceipt(
            bundleHash: request.bundleHash,
            merchantCreditRef: request.idempotencyKey,
            merchantID: request.merchantID,
            mintKeyID: mintConfiguration.mintKeyID,
            issuedAt: occurredAt,
            signature: receiptSignature
        )
        try await walletEventStore.insertWalletEvent(
            WalletEventRecord(
                walletID: firstIssuedCoin.walletID,
                customerID: firstIssuedCoin.customerID,
                quoteID: firstIssuedCoin.quoteID,
                cashEventID: nil,
                reservationID: firstIssuedCoin.reservationID,
                eventType: .mintRedeemed,
                unitAmount: amount,
                nokReferenceAmountOre: amount,
                occurredAt: occurredAt
            )
        )

        let response = RedeemWithLedgerResponse(
            accepted: true,
            alreadyProcessed: false,
            rejectionReason: nil,
            receipt: receipt,
            walletID: firstIssuedCoin.walletID,
            customerID: firstIssuedCoin.customerID,
            resourceID: request.resourceID,
            merchantID: request.merchantID,
            redeemedNOKOre: amount,
            occurredAt: occurredAt
        )
        try await storeIdempotentResponse(
            response,
            key: request.idempotencyKey,
            action: .redeemWithLedger,
            identityScope: request.merchantID,
            resourceID: request.resourceID,
            requestHash: requestHash
        )
        return response
    }

    public func reconcile(windowStart: Date, windowEnd: Date) async throws -> ReconciliationReport {
        try await reconciliationStore.reconciliationReport(windowStart: windowStart, windowEnd: windowEnd)
