    private func resolveWallet(customerID: String, walletID: UUID?) async throws -> StoredWallet {
        if let walletID {
            guard let wallet = try await walletStore.wallet(walletID: walletID) else {
                throw FundingServiceError.unknownWallet(walletID)
            }
            return wallet
        }

        if let existing = try await walletStore.wallet(customerID: customerID, currency: "NOK") {
            return existing
        }

        let wallet = StoredWallet(customerID: customerID)
        try await walletStore.upsertWallet(wallet)
        return wallet
    }

    private func resolvePaymentForCapture(
        providerPaymentRef: String,
        envelope: StripeWebhookEnvelope,
        amount: Int64
    ) async throws -> ProviderPaymentRecord {
        if let existing = try await providerPaymentStore.payment(provider: .stripe, providerPaymentRef: providerPaymentRef) {
            return existing
        }

        guard let metadata = envelope.data.object.metadata,
              let customerID = metadata["customer_id"] else {
            throw FundingServiceError.unknownProviderPaymentRef(providerPaymentRef)
        }

        let walletID: UUID
        if let rawWalletID = metadata["wallet_id"], let parsed = UUID(uuidString: rawWalletID) {
            walletID = parsed
            if try await walletStore.wallet(walletID: parsed) == nil {
                try await walletStore.upsertWallet(StoredWallet(walletID: parsed, customerID: customerID))
            }
        } else {
            let wallet = try await resolveWallet(customerID: customerID, walletID: nil)
            walletID = wallet.walletID
        }

        let quoteID = metadata["quote_id"].flatMap(UUID.init(uuidString:))
        guard let resolvedQuoteID = quoteID else {
            throw FundingServiceError.invalidStripeEventPayload
        }

        let payment = ProviderPaymentRecord(
            provider: .stripe,
            providerPaymentRef: providerPaymentRef,
            walletID: walletID,
            customerID: customerID,
            quoteID: resolvedQuoteID,
            requestedAmountNOKOre: amount,
            status: .captured,
            checkoutURL: nil
        )
        try await providerPaymentStore.upsertPayment(payment)
        return payment
    }

    private func incrementWalletBalance(walletID: UUID, amount: Int64) async throws {
        guard let existing = try await walletStore.balance(walletID: walletID) else {
            throw FundingServiceError.unknownWallet(walletID)
        }

        let updated = WalletBalanceProjection(
            walletID: walletID,
            unitName: existing.unitName,
            availableUnits: existing.availableUnits + amount,
            reservedUnits: existing.reservedUnits,
            consumedUnits: existing.consumedUnits,
            availableNOKOre: existing.availableNOKOre + amount,
            reservedNOKOre: existing.reservedNOKOre,
            consumedNOKOre: existing.consumedNOKOre,
            updatedAt: Date()
        )
        try await walletStore.upsertBalance(updated)
    }

    private func replayIdempotentResponse<Response: Codable>(
        key: String?,
        action: LedgerOperationAction,
        identityScope: String,
        resourceID: String?,
        requestHash: String
    ) async throws -> Response? {
        guard let key = normalizedIdempotencyKey(key) else {
            return nil
        }
        guard let existing = try await ledgerIdempotencyStore.ledgerIdempotencyRecord(idempotencyKey: key) else {
            return nil
        }
        guard existing.action == action,
              existing.identityScope == identityScope,
              existing.resourceID == resourceID,
              existing.requestHash == requestHash else {
            throw FundingServiceError.idempotencyKeyConflict(key)
        }
        return try ledgerDecoder.decode(Response.self, from: existing.responseBody)
    }

    private func storeIdempotentResponse<Response: Encodable>(
        _ response: Response,
        key: String?,
        action: LedgerOperationAction,
        identityScope: String,
        resourceID: String?,
        requestHash: String
    ) async throws {
        guard let key = normalizedIdempotencyKey(key) else {
            return
        }
        let body = try ledgerEncoder.encode(response)
        let record = LedgerIdempotencyRecord(
            idempotencyKey: key,
            action: action,
            identityScope: identityScope,
            resourceID: resourceID,
            requestHash: requestHash,
            responseBody: body,
            createdAt: now()
        )
        try await ledgerIdempotencyStore.upsertLedgerIdempotencyRecord(record)
    }

    private func normalizedIdempotencyKey(_ key: String?) -> String? {
        let trimmed = key?.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed?.isEmpty == false ? trimmed : nil
    }

    private func hashRequest(_ values: [String: String]) -> String {
        let body = values
            .sorted { $0.key < $1.key }
            .map { "\($0.key)=\($0.value)" }
            .joined(separator: "|")
        return FundingHashing.sha256Hex(Data(body.utf8))
    }

    private func makeIssuedCoin(
        reservation: WalletReservationRecord,
        denomination: UInt64,
        idempotencyKey: String,
        index: Int
    ) -> Coin {
        let serialSeed = [
            reservation.reservationID.uuidString,
            idempotencyKey,
            "\(index)",
            "\(denomination)"
        ].joined(separator: "|")
        let serial = "dimy_\(FundingHashing.sha256Hex(Data(serialSeed.utf8)).prefix(32))"
        let signature = mintSigner.signBlindedMessage(
            "issue|\(serial)|\(denomination)|\(reservation.reservationID.uuidString)",
            mintKeyID: mintConfiguration.mintKeyID
        )
        return Coin(
            denomMinorUnits: denomination,
            serial: serial,
            mintKeyID: mintConfiguration.mintKeyID,
            signature: signature
        )
    }

    private func resolveIssuedCoins(for bundle: SpendBundle) async throws -> [IssuedCoinRecord] {
        var issuedCoins: [IssuedCoinRecord] = []
        for coin in bundle.coins {
            guard let issued = try await issuedCoinStore.issuedCoin(serial: coin.serial) else {
                throw FundingServiceError.unknownIssuedCoin(coin.serial)
            }
            guard issued.amountNOKOre == Int64(coin.denomMinorUnits) else {
                throw FundingServiceError.invalidStripeEventPayload
            }
            issuedCoins.append(issued)
        }
        return issuedCoins
    }

    private func redeemRejectedResponse(
        _ request: RedeemWithLedgerRequest,
        reason: RedeemRejectionReason
    ) -> RedeemWithLedgerResponse {
        RedeemWithLedgerResponse(
            accepted: false,
            alreadyProcessed: false,
            rejectionReason: reason,
            receipt: nil,
            walletID: nil,
            customerID: nil,
            resourceID: request.resourceID,
            merchantID: request.merchantID,
            redeemedNOKOre: 0,
            occurredAt: now()
        )
    }

    private func headerValue(_ name: String, in headers: [String: String]) -> String? {
        headers.first { key, _ in key.caseInsensitiveCompare(name) == .orderedSame }?.value
    }

    private func normalizedResourceID(_ resourceID: String?) -> String? {
        let trimmed = resourceID?.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed?.isEmpty == false ? trimmed : nil
    }

    private func makeProviderPaymentRef(provider: PaymentProvider) -> String {
        "\(provider.rawValue)_\(UUID().uuidString.replacingOccurrences(of: "-", with: "").lowercased())"
    }
}

