import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif

public protocol PaymentSessionCreating: Sendable {
    func createStripeCheckoutSession(_ request: StripeCheckoutSessionRequest) async throws -> StripeCheckoutSessionResult
}

public struct FailClosedPaymentSessionCreator: PaymentSessionCreating {
    public init() {}

    public func createStripeCheckoutSession(_ request: StripeCheckoutSessionRequest) async throws -> StripeCheckoutSessionResult {
        _ = request
        throw FundingServiceError.stripeCheckoutNotConfigured
    }
}

public struct EnvironmentStripePaymentSessionCreator: PaymentSessionCreating {
    private let environment: [String: String]
    private let session: URLSession

    public init(
        environment: [String: String] = ProcessInfo.processInfo.environment,
        session: URLSession = .shared
    ) {
        self.environment = environment
        self.session = session
    }

    public func createStripeCheckoutSession(_ request: StripeCheckoutSessionRequest) async throws -> StripeCheckoutSessionResult {
        guard let secretKey = environment["STRIPE_SECRET_KEY"]?
            .trimmingCharacters(in: .whitespacesAndNewlines),
              !secretKey.isEmpty else {
            throw FundingServiceError.stripeCheckoutNotConfigured
        }

        var urlRequest = URLRequest(url: URL(string: "https://api.stripe.com/v1/checkout/sessions")!)
        urlRequest.httpMethod = "POST"
        urlRequest.setValue("Bearer \(secretKey)", forHTTPHeaderField: "Authorization")
        urlRequest.setValue(request.providerPaymentRef, forHTTPHeaderField: "Idempotency-Key")
        urlRequest.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")
        urlRequest.httpBody = formURLEncodedBody(
            [
                "mode": "payment",
                "success_url": request.returnURL,
                "cancel_url": request.cancelURL,
                "client_reference_id": request.providerPaymentRef,
                "line_items[0][quantity]": "1",
                "line_items[0][price_data][currency]": request.currency.lowercased(),
                "line_items[0][price_data][unit_amount]": "\(request.amountNOKOre)",
                "line_items[0][price_data][product_data][name]": "DiMy usage quota top-up",
                "metadata[provider_payment_ref]": request.providerPaymentRef,
                "metadata[wallet_id]": request.walletID.uuidString,
                "metadata[customer_id]": request.customerID,
                "metadata[quote_id]": request.quoteID.uuidString
            ]
        )

        let (data, response) = try await session.data(for: urlRequest)
        guard let httpResponse = response as? HTTPURLResponse,
              (200..<300).contains(httpResponse.statusCode) else {
            throw FundingServiceError.stripeCheckoutNotConfigured
        }

        let stripeResponse = try JSONDecoder().decode(StripeCheckoutSessionAPIResponse.self, from: data)
        guard let checkoutURL = stripeResponse.url, !checkoutURL.isEmpty else {
            throw FundingServiceError.stripeCheckoutNotConfigured
        }

        return StripeCheckoutSessionResult(
            checkoutURL: checkoutURL,
            providerPaymentRef: stripeResponse.id
        )
    }

    private func formURLEncodedBody(_ values: [String: String]) -> Data {
        values
            .sorted { $0.key < $1.key }
            .map { key, value in
                "\(percentEncode(key))=\(percentEncode(value))"
            }
            .joined(separator: "&")
            .data(using: .utf8)!
    }

    private func percentEncode(_ value: String) -> String {
        var allowed = CharacterSet.urlQueryAllowed
        allowed.remove(charactersIn: ":#[]@!$&'()*+,;=")
        return value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
    }
}

private struct StripeCheckoutSessionAPIResponse: Decodable {
    let id: String
    let url: String?
}

